static inline int8_t _rf_predict_tree(
    const int8_t *feat, const float *thr,
    const int16_t *left, const int16_t *right,
    const int8_t *cls_arr, const float *x_scaled)
{
  int16_t node = 0;
  while (feat[node] >= 0) {
    if (x_scaled[feat[node]] <= thr[node])
      node = left[node];
    else
      node = right[node];
  }
  return cls_arr[node];
}

// Scale one feature vector in-place (fills x_out from x_raw)
static inline void rf_scale_features(const float *x_raw, float *x_out) {
  for (int i = 0; i < RF_NUM_FEATURES; i++) {
    float denom = RF_FEAT_MAX[i] - RF_FEAT_MIN[i];
    if (denom < 1e-6f) denom = 1.0f;
    x_out[i] = 2.0f * (x_raw[i] - RF_FEAT_MIN[i]) / denom - 1.0f;
  }
}

// Main inference: x_raw = 16 unscaled features, returns class 0-3
// votes[] is optional output (NULL to skip); pass float[4]
static inline int8_t rf_predict(const float *x_raw, float *votes) {
  float x_scaled[RF_NUM_FEATURES];
  rf_scale_features(x_raw, x_scaled);
  int counts[RF_NUM_CLASSES] = {0};

  counts[_rf_predict_tree(RF_T0_FEAT, RF_T0_THR,
    RF_T0_LEFT, RF_T0_RIGHT, RF_T0_CLASS, x_scaled)]++;
  counts[_rf_predict_tree(RF_T1_FEAT, RF_T1_THR,
    RF_T1_LEFT, RF_T1_RIGHT, RF_T1_CLASS, x_scaled)]++;
  counts[_rf_predict_tree(RF_T2_FEAT, RF_T2_THR,
    RF_T2_LEFT, RF_T2_RIGHT, RF_T2_CLASS, x_scaled)]++;
  counts[_rf_predict_tree(RF_T3_FEAT, RF_T3_THR,
    RF_T3_LEFT, RF_T3_RIGHT, RF_T3_CLASS, x_scaled)]++;
  counts[_rf_predict_tree(RF_T4_FEAT, RF_T4_THR,
    RF_T4_LEFT, RF_T4_RIGHT, RF_T4_CLASS, x_scaled)]++;
  counts[_rf_predict_tree(RF_T5_FEAT, RF_T5_THR,
    RF_T5_LEFT, RF_T5_RIGHT, RF_T5_CLASS, x_scaled)]++;
  counts[_rf_predict_tree(RF_T6_FEAT, RF_T6_THR,
    RF_T6_LEFT, RF_T6_RIGHT, RF_T6_CLASS, x_scaled)]++;
  counts[_rf_predict_tree(RF_T7_FEAT, RF_T7_THR,
    RF_T7_LEFT, RF_T7_RIGHT, RF_T7_CLASS, x_scaled)]++;
  counts[_rf_predict_tree(RF_T8_FEAT, RF_T8_THR,
    RF_T8_LEFT, RF_T8_RIGHT, RF_T8_CLASS, x_scaled)]++;
  counts[_rf_predict_tree(RF_T9_FEAT, RF_T9_THR,
    RF_T9_LEFT, RF_T9_RIGHT, RF_T9_CLASS, x_scaled)]++;
  counts[_rf_predict_tree(RF_T10_FEAT, RF_T10_THR,
    RF_T10_LEFT, RF_T10_RIGHT, RF_T10_CLASS, x_scaled)]++;
  counts[_rf_predict_tree(RF_T11_FEAT, RF_T11_THR,
    RF_T11_LEFT, RF_T11_RIGHT, RF_T11_CLASS, x_scaled)]++;
  counts[_rf_predict_tree(RF_T12_FEAT, RF_T12_THR,
    RF_T12_LEFT, RF_T12_RIGHT, RF_T12_CLASS, x_scaled)]++;
  counts[_rf_predict_tree(RF_T13_FEAT, RF_T13_THR,
    RF_T13_LEFT, RF_T13_RIGHT, RF_T13_CLASS, x_scaled)]++;
  counts[_rf_predict_tree(RF_T14_FEAT, RF_T14_THR,
    RF_T14_LEFT, RF_T14_RIGHT, RF_T14_CLASS, x_scaled)]++;
  counts[_rf_predict_tree(RF_T15_FEAT, RF_T15_THR,
    RF_T15_LEFT, RF_T15_RIGHT, RF_T15_CLASS, x_scaled)]++;
  counts[_rf_predict_tree(RF_T16_FEAT, RF_T16_THR,
    RF_T16_LEFT, RF_T16_RIGHT, RF_T16_CLASS, x_scaled)]++;
  counts[_rf_predict_tree(RF_T17_FEAT, RF_T17_THR,
    RF_T17_LEFT, RF_T17_RIGHT, RF_T17_CLASS, x_scaled)]++;
  counts[_rf_predict_tree(RF_T18_FEAT, RF_T18_THR,
    RF_T18_LEFT, RF_T18_RIGHT, RF_T18_CLASS, x_scaled)]++;
  counts[_rf_predict_tree(RF_T19_FEAT, RF_T19_THR,
    RF_T19_LEFT, RF_T19_RIGHT, RF_T19_CLASS, x_scaled)]++;
  if (votes) {
    for (int i=0;i<RF_NUM_CLASSES;i++)
      votes[i]=(float)counts[i]/20.0f;
  }
  int best=0; for(int i=1;i<RF_NUM_CLASSES;i++) if(counts[i]>counts[best]) best=i;
  return (int8_t)best;
}
